 <div class="ri-chart-grid"><?php $charts=[];foreach($data['charts'] as $i=>$chart)$charts[]=riChart('rs-chart-'.$i,$chart['title'],'Based on the active report filters',$chart['labels'],$chart['values'],$chart['kind']);?></div>
